  (s_regions st2) !! rid = Some r2 -> r_kind r2 = RKGroup ->
  munch [(slo, shi); (831388, 831392); (r_base r2, r_base r2 + round_up_pg (r_len r2))]%Z m4 m5 ->
  alloc_ceiling <= slo ->
  rmrep (drop_region rid st2) m5.
